def total_n_queens(n):
    cols = set(); d1 = set(); d2 = set(); cnt = 0
    def bt(r):
        nonlocal cnt
        if r == n: cnt += 1; return
        for c in range(n):
            if c in cols or r - c in d1 or r + c in d2: continue
            cols.add(c); d1.add(r - c); d2.add(r + c); bt(r + 1); cols.discard(c); d1.discard(r - c); d2.discard(r + c)
    bt(0); return cnt

