int cnt_, full_;
void q_(int cols, int d1, int d2) { if (cols == full_) { cnt_++; return; } int avail = full_ & ~(cols | d1 | d2); while (avail) { int b = avail & -avail; avail -= b; q_(cols | b, (d1 | b) << 1, (d2 | b) >> 1); } }
int totalNQueens(int n) { cnt_ = 0; full_ = (1 << n) - 1; q_(0, 0, 0); return cnt_; }
